import { Hero } from "march/landing"
import { sparkles } from "march/icons"

// fırlatmaya kalan gün: her basışta bir gün azalır, başlık ve vurgu birlikte değişir; sıfırda görünüm aurora olur
export function LaunchCountdown() {
  let $days = 3
  return <div>{() => { const days = $days; return <Hero variant={days > 0 ? "centered" : "aurora"} size="md" level={2}
    eyebrow={days > 0 ? `${days} gün kaldı` : "Yayında!"}
    title={days > 0 ? `Fırlatmaya ${days} gün` : "March yayında"} highlight={days > 0 ? `${days} gün` : "yayında"}
    lead="Sinyaller, derleyici ve bileşenler tek pakette."
    actions={[{ label: days > 0 ? "Bir gün ileri sar" : "Baştan başlat", icon: sparkles, onClick: () => $days = $days > 0 ? $days - 1 : 3 }]} /> }}</div>
}

import { Hero } from "march/landing"
import { arrowRight, mapPin } from "march/icons"
import { toast } from "march/ui"

// bir kahvecinin açılış ekranı: solda metin ve eylemler, sağda menü kartı (split görünüm)
const MenuCard = () => <div sx={{ flex: "col", gap: 2, p: 4, radius: 3 }} class="cafe-menu" role="list" aria-label="Bugünün menüsü">
  {[["Filtre kahve", "65 ₺"], ["Flat white", "85 ₺"], ["Tarçınlı çörek", "70 ₺"]].map(([name, price]) =>
    <div role="listitem" sx={{ flex: ["row", "between"], gap: 4 }}><span>{name}</span><strong>{price}</strong></div>)}
</div>

export function CafeHero() {
  return <Hero variant="split" size="md" level={2} eyebrow="Kadıköy · 08.00–22.00" eyebrowHref="#harita"
    title="Sabah kahven hazır" highlight="hazır"
    lead="Taze kavrulmuş çekirdek, ev yapımı çörek. Sıraya girme: yoldayken sipariş ver, gelince al."
    actions={[{ label: "Sipariş ver", iconEnd: arrowRight, onClick: () => toast("Siparişin alındı") }, { label: "Yol tarifi", icon: mapPin, href: "#harita" }]}
    note="İlk kahve bizden" media={<MenuCard /> as Node} />
}

import { Hero } from "march/landing"
import { Segmented, Toggle, Card } from "march/ui"
import { arrowRight, play } from "march/icons"

// Hero'nun bütün özellikleri bir arada: yedi görünüm, hiza, yükseklik, başlık düzeyi, üst etiket bağlantısı ve oku,
// vurgu, açıklama, eylemler, not, medya, video, parallax katmanları, aurora renkleri, süs katmanları, giriş hareketi,
// pencere çubuğu, eğim, sınıf ve içerik (children). Hero çoğu prop'u bir kez okur: durumları {() => …} bloğunda
// okuyunca, biri değişince Hero yeniden çizilir
const VARIANTS = ["centered", "split", "video", "mesh", "aurora", "product", "parallax"] as const

const Screen = () => <div sx={{ flex: ["col", "center"], gap: 2, p: 6 }} aria-label="Uygulama ekranı" role="img">
  <strong>Bugünün etkinlikleri</strong><span sx={{ color: "muted" }}>3 yeni buluşma</span>
</div>

export function HeroLab() {
  let $variant: (typeof VARIANTS)[number] = "product"
  let $start = false
  let $backdrop = true
  let $tilt = true
  let $bar = true
  let $joined = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Görünüm" options={VARIANTS.map((v) => ({ value: v, label: v }))} bind:value={$variant} />
        <Toggle label="Başa hizala" bind:value={$start} />
        <Toggle label="Süs katmanları" bind:value={$backdrop} />
        <Toggle label="Eğim" bind:value={$tilt} />
        <Toggle label="Pencere çubuğu" bind:value={$bar} />
      </div>
    </Card>
    {() => {
      // bu satırda okunan durumlar değişince Hero yeniden çizilir
      const variant = $variant, start = $start, backdrop = $backdrop, tilt = $tilt, bar = $bar, joined = $joined
      return <Hero variant={variant} align={start ? "start" : "center"} size="md" level={2} class="lab-hero"
      eyebrow="Yeni: canlı etkinlikler" eyebrowHref="#yenilikler" eyebrowArrow={<span aria-hidden="true">↗</span>}
      title="Bugün kiminle buluşuyorsun?" highlight="buluşuyorsun"
      lead="Yakınındaki etkinlikleri bul, bir dokunuşla katıl."
      actions={[{ label: `Katıl (${joined})`, iconEnd: arrowRight, onClick: () => $joined++ }, { label: "Tanıtımı izle", icon: play, variant: "secondary" }]}
      note="Ücretsiz · kart gerekmez" media={<Screen /> as Node}
      video={{ src: "/media/hadi-waves.webm", poster: "/media/hadi-waves.jpg" }}
      layers={[{ content: <div class="lab-sky" style={{ inlineSize: "100%", blockSize: "100%" }} />, speed: 0.4 }]}
      colors={["#ff7a59", "#7c5cff", "#2bb8ff"]} backdrop={backdrop} reveal="blur" frameBar={bar} tilt={tilt}>
      <small sx={{ color: "muted" }}>12 şehirde, 40 bin kişi</small>
    </Hero>
    }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { HeroLab } from "./HeroLab.tsx"

// HeroLab'in testleri: kaydedince Testler sekmesinde çalışır
test("başlık ikinci düzeyde, vurgulu kısım ayrı bir öğede", () => {
  const s = renderTest(() => <HeroLab />)
  const h = s.container.querySelector("h2")
  expect(h?.textContent).toContain("Bugün kiminle buluşuyorsun?")
  expect(h?.querySelector(".m-hero-hl")?.textContent).toBe("buluşuyorsun")
})

test("ilk eylem sayar: Katıl (0) → Katıl (1)", async () => {
  const s = renderTest(() => <HeroLab />)
  await s.click("Katıl (0)")
  expect(s.find("Katıl (1)")).not.toBe(null)
})

test("üst etiket bir bağlantı; not ve içerik görünür", () => {
  const s = renderTest(() => <HeroLab />)
  expect(s.container.querySelector('a[href="#yenilikler"]')).not.toBe(null)
  expect(s.container.textContent).toContain("Ücretsiz · kart gerekmez")
  expect(s.container.textContent).toContain("12 şehirde, 40 bin kişi")
})

test("ürün görünümünde pencere çubuğu var; anahtar kapatınca gider", async () => {
  const s = renderTest(() => <HeroLab />)
  expect(s.container.querySelector(".m-hero-frame-bar")).not.toBe(null)
  await s.click("Pencere çubuğu")
  expect(s.container.querySelector(".m-hero-frame-bar")).toBe(null)
})
